/* --- RESET & VARIABLES --- */
* {
    margin: 0;
    padding: 0;
    box-sizing: border-box;
}

body {
    font-family: 'Lato', sans-serif;
    background-color: #000;
    overflow-x: hidden;
}

:root {
    --gold-solid: #D4AF37;
    --gold-gradient: linear-gradient(135deg, #BF953F, #FCF6BA, #B38728, #FBF5B7, #AA771C);
    --maroon-deep: #5D1A1A;
    --spotify-green: #1DB954;
}

/* --- HERO CONTAINER (DESKTOP) --- */
.hero-split-container {
    display: flex;
    flex-direction: row;
    width: 100vw;
    height: 100vh;
    background-color: #111;
}

/* --- INDIVIDUAL PANELS --- */
.hero-panel {
    position: relative;
    flex: 1; /* Equal width by default */
    display: flex;
    align-items: flex-end;
    justify-content: center;
    overflow: hidden;
    transition: flex 0.6s cubic-bezier(0.25, 0.8, 0.25, 1);
    border-right: 1px solid rgba(212, 175, 55, 0.2);
    cursor: pointer;
}

.hero-panel:last-child {
    border-right: none;
}

/* Background Image Setup */
.panel-bg {
    position: absolute;
    top: 0; left: 0; width: 100%; height: 100%;
    background-size: cover;
    background-position: center;
    transition: transform 1s ease, filter 0.6s ease;
    filter: brightness(0.6) grayscale(20%);
    z-index: 1;
}

/* Gradient Overlay for Text Readability */
.panel-overlay {
    position: absolute;
    top: 0; left: 0; width: 100%; height: 100%;
    background: linear-gradient(to top, rgba(0,0,0,0.95) 5%, rgba(0,0,0,0.4) 60%, transparent);
    z-index: 2;
}

/* Content Box */
.panel-content {
    position: relative;
    z-index: 3;
    width: 100%;
    padding: 40px 20px;
    text-align: center;
    display: flex;
    flex-direction: column;
    align-items: center;
}

/* Typography */
.panel-direction {
    font-size: 0.85rem;
    letter-spacing: 2px;
    color: var(--gold-solid);
    text-transform: uppercase;
    font-weight: 700;
    margin-bottom: 8px;
    transition: 0.4s ease;
}

.panel-title {
    font-family: 'Cinzel', serif;
    font-size: 1.8rem;
    color: #fff;
    line-height: 1.2;
    margin-bottom: 15px;
    transition: 0.4s ease;
}

/* Hide Extra Details on Desktop by Default */
.panel-details {
    max-height: 0;
    opacity: 0;
    overflow: hidden;
    transition: all 0.5s ease;
    width: 100%;
}

.panel-veda {
    color: #ddd;
    font-style: italic;
    margin-bottom: 20px;
    font-size: 1rem;
}

/* Button Layout */
.action-wrapper {
    display: flex;
    flex-direction: column;
    gap: 12px;
    width: 100%;
    max-width: 280px;
    margin: 0 auto;
}

.hero-btn {
    display: block;
    width: 100%;
    padding: 12px 15px;
    background: var(--gold-gradient);
    color: var(--maroon-deep);
    text-decoration: none;
    font-weight: 800;
    border-radius: 5px;
    font-size: 0.9rem;
    box-shadow: 0 4px 10px rgba(0,0,0,0.3);
    border: 2px solid transparent;
    transition: all 0.3s ease;
}

.hero-btn.outline {
    background: transparent;
    border-color: var(--gold-solid);
    color: var(--gold-solid);
}

.hero-btn.highlight-btn {
    background-color: var(--spotify-green);
    color: #fff;
    border-color: var(--spotify-green);
}

/* Button Hovers */
.hero-btn:hover { transform: translateY(-3px); }
.hero-btn.outline:hover { background: var(--gold-solid); color: #000; }
.hero-btn.highlight-btn:hover { background-color: #1ed760; border-color: #1ed760; box-shadow: 0 0 15px rgba(29, 185, 84, 0.6); }

/* --- HOVER EFFECTS (DESKTOP ONLY) --- */
@media (min-width: 1025px) {
    .hero-panel:hover {
        flex: 2.5; /* Panel expands */
    }
    .hero-panel:hover .panel-bg {
        transform: scale(1.05);
        filter: brightness(1) grayscale(0%);
    }
    .hero-panel:hover .panel-title {
        font-size: 2.4rem;
        color: var(--gold-solid);
    }
    .hero-panel:hover .panel-details {
        max-height: 300px; /* Reveals buttons */
        opacity: 1;
        margin-top: 10px;
    }
}

/* =========================================
   TABLET VIEW (2x2 GRID - Perfect Balance) 
   ========================================= */
@media (max-width: 1024px) {
    .hero-split-container {
        flex-wrap: wrap; /* Allows breaking into rows */
    }
    .hero-panel {
        flex: 0 0 50%; /* Each panel takes exactly 50% width */
        height: 50vh;  /* Each panel takes 50% height */
        border-bottom: 1px solid rgba(212, 175, 55, 0.2);
    }
    .hero-panel:nth-child(even) {
        border-right: none;
    }
    /* Always show details on touch devices */
    .panel-details {
        max-height: 500px;
        opacity: 1;
        overflow: visible;
    }
    .panel-bg {
        filter: brightness(0.8) grayscale(0%);
    }
}

/* =========================================
   MOBILE VIEW (Stacked vertically) 
   ========================================= */
@media (max-width: 768px) {
    .hero-split-container {
        flex-direction: column;
        flex-wrap: nowrap;
        height: auto; /* Let the page scroll normally */
    }
    .hero-panel {
        flex: 0 0 100%; /* Full width */
        height: auto;
        min-height: 450px; /* Gives enough room for all buttons */
        border-right: none;
        border-bottom: 2px solid rgba(212, 175, 55, 0.3);
        padding-top: 50px; /* Space at top of image */
    }

    .panel-title {
        font-size: 1.8rem;
    }

    /* Make buttons slightly smaller for mobile fit */
    .hero-btn {
        padding: 10px 15px;
        font-size: 0.85rem;
    }
}

/* =========================================
   GENERAL STYLES
   ========================================= */
body {
    font-family: 'Georgia', serif; /* Classic serif font for a letter feel */
    background-color: #f4f1ea; /* Soft off-white paper background */
    color: #2c2c2c;
    margin: 0;
    padding: 20px;
    line-height: 1.8;
}

/* For SEO purposes only, hidden from users */
.visually-hidden {
    position: absolute;
    width: 1px;
    height: 1px;
    margin: -1px;
    padding: 0;
    overflow: hidden;
    clip: rect(0, 0, 0, 0);
    border: 0;
}

/* =========================================
   TOP HEADER BANNER IMAGE (NEW)
   ========================================= */
.top-header-banner {
    width: 100%;
    max-width: 900px;
    margin: 10px auto 30px auto;
    display: block;
    border-radius: 12px;
    box-shadow: 0 10px 30px rgba(0,0,0,0.15);
    border: 3px solid #D4AF37; /* Golden border */
}

/* =========================================
   CONTROLS & BUTTONS (ENHANCED WITH AUTO RANDOM GLOW)
   ========================================= */
.controls {
    text-align: center;
    margin-bottom: 20px;
}

button {
    background-color: #8b2b2b; /* Deep red/maroon color */
    color: white;
    border: none;
    padding: 12px 25px;
    font-size: 16px;
    cursor: pointer;
    border-radius: 5px;
    transition: background-color 0.3s, box-shadow 0.2s, transform 0.1s;
    font-family: 'Arial', sans-serif;
    box-shadow: 0 4px 6px rgba(0,0,0,0.2);

    /* ===== AUTOMATIC RANDOM LIGHT-UP ANIMATION ===== */
    animation-name: randomGlow;
    animation-iteration-count: infinite;
    animation-timing-function: ease-in-out;
    animation-fill-mode: both;
}

/* Keyframes: creates a "light up" state with golden glow and slight scaling */
@keyframes randomGlow {
    0% {
        background-color: #8b2b2b;
        box-shadow: 0 4px 6px rgba(0,0,0,0.2);
        transform: scale(1);
        color: white;
    }
    15% {
        background-color: #e09d32;  /* warm golden flash */
        box-shadow: 0 0 16px 5px rgba(218, 165, 32, 0.8), 0 0 0 2px rgba(255, 215, 0, 0.5);
        transform: scale(1.03);
        color: #2c1a0c;
    }
    30% {
        background-color: #8b2b2b;
        box-shadow: 0 4px 6px rgba(0,0,0,0.2);
        transform: scale(1);
        color: white;
    }
    100% {
        background-color: #8b2b2b;
        box-shadow: 0 4px 6px rgba(0,0,0,0.2);
        transform: scale(1);
        color: white;
    }
}

/* ---- RANDOMIZED DURATIONS & DELAYS (creates unpredictable rhythm) ---- */
/* Each button gets its own unique timing – feels completely chaotic & natural */
button:nth-child(1) { animation-duration: 2.2s; animation-delay: 0.1s; }
button:nth-child(2) { animation-duration: 3.8s; animation-delay: 0.9s; }
button:nth-child(3) { animation-duration: 1.6s; animation-delay: 1.4s; }
button:nth-child(4) { animation-duration: 4.0s; animation-delay: 0.3s; }
button:nth-child(5) { animation-duration: 2.9s; animation-delay: 2.0s; }
button:nth-child(6) { animation-duration: 3.1s; animation-delay: 0.6s; }
button:nth-child(7) { animation-duration: 1.9s; animation-delay: 1.8s; }
button:nth-child(8) { animation-duration: 3.5s; animation-delay: 0.0s; }
button:nth-child(9) { animation-duration: 2.4s; animation-delay: 1.2s; }
button:nth-child(10){ animation-duration: 4.2s; animation-delay: 0.7s; }
button:nth-child(11){ animation-duration: 1.7s; animation-delay: 2.3s; }
button:nth-child(12){ animation-duration: 3.3s; animation-delay: 0.4s; }
button:nth-child(13){ animation-duration: 2.6s; animation-delay: 1.6s; }
button:nth-child(14){ animation-duration: 3.9s; animation-delay: 1.1s; }
button:nth-child(15){ animation-duration: 2.1s; animation-delay: 0.8s; }
button:nth-child(16){ animation-duration: 3.7s; animation-delay: 1.9s; }
button:nth-child(17){ animation-duration: 1.4s; animation-delay: 2.6s; }
button:nth-child(18){ animation-duration: 4.4s; animation-delay: 0.2s; }
button:nth-child(19){ animation-duration: 2.8s; animation-delay: 1.3s; }
button:nth-child(20){ animation-duration: 3.2s; animation-delay: 2.2s; }

/* Hover interaction: pause the random glow, give full control to the user */
button:hover {
    background-color: #631d1d;
    animation: none;           /* stops random flashing on hover */
    transform: translateY(-2px);
    box-shadow: 0 6px 12px rgba(0,0,0,0.25);
}

/* =========================================
   A4 PAPER EFFECT (THE LETTER)
   ========================================= */
.a4-page {
    background-color: #fffdf7;
    width: 100%;
    max-width: 850px;
    margin: 0 auto;
    padding: 50px 60px;
    box-shadow: 0 0 20px rgba(0, 0, 0, 0.1);
    box-sizing: border-box;
    border: 1px solid #e0d8c3;
    border-radius: 2px;
}

/* =========================================
   TYPOGRAPHY INSIDE THE LETTER
   ========================================= */
h1 {
    text-align: center;
    color: #8b2b2b;
    font-size: 2em;
    margin-bottom: 30px;
    border-bottom: 2px solid #d4c8b2;
    padding-bottom: 10px;
}

p {
    text-align: justify;
    margin-bottom: 20px;
    font-size: 1.1em;
}

.highlight {
    font-weight: bold;
    color: #b54911;
}

a {
    color: #0056b3;
    text-decoration: underline;
}

a:hover {
    color: #003d82;
}

/* =========================================
   IMAGES INSIDE THE LETTER
   ========================================= */
.article-image {
    width: 100%;
    max-width: 600px;
    height: auto;
    display: block;
    margin: 30px auto;
    border: 5px solid #eaeaea;
    box-shadow: 0 4px 10px rgba(0,0,0,0.1);
    border-radius: 5px;
}

/* =========================================
   DIVIDER BETWEEN HINDI & ENGLISH
   ========================================= */
.divider {
    border: 0;
    height: 1px;
    background-image: linear-gradient(to right, rgba(0, 0, 0, 0), rgba(139, 43, 43, 0.5), rgba(0, 0, 0, 0));
    margin: 50px 0;
}

/* =========================================
   RESPONSIVE DESIGN (MOBILE)
   ========================================= */
@media screen and (max-width: 768px) {
    body {
        padding: 10px;
    }

    .top-header-banner {
        width: 95%;
        border-radius: 8px;
        margin-bottom: 20px;
    }

    .a4-page {
        padding: 30px 20px;
    }

    h1 {
        font-size: 1.6em;
    }

    p {
        font-size: 1em;
        text-align: left; /* Better readability on small screens */
    }
}

/* ==============================================================
   2015 ANYAY PRATIKAR YATRA GALLERY STYLES
   ============================================================== */

.gallery-section {
    width: 100%;
    max-width: 1000px;
    margin: 40px auto;
    background: #ffffff;
    padding: 30px;
    border-radius: 12px;
    box-shadow: 0 10px 30px rgba(0, 0, 0, 0.08);
    font-family: 'Lato', sans-serif;
    border-top: 5px solid #E67E22;
}

/* Title Area */
.gallery-header {
    text-align: center;
    margin-bottom: 25px;
}

.gallery-header h2 {
    font-family: 'Cinzel', serif;
    color: #D35400;
    font-size: 2rem;
    margin-bottom: 10px;
    font-weight: 700;
}

.gallery-header p {
    color: #555;
    font-size: 1.1rem;
    font-weight: 600;
}

/* Slider Wrapper - Ensures smooth image display */
.slider-wrapper {
    position: relative;
    width: 100%;
    overflow: hidden;
    border-radius: 8px;
    aspect-ratio: 16/9; /* Standard widescreen ratio */
    background-color: #000; /* Dark background to handle varied image sizes gracefully */
    box-shadow: 0 4px 15px rgba(0, 0, 0, 0.2);
}

.slides {
    display: flex;
    width: 100%;
    height: 100%;
    transition: transform 0.8s cubic-bezier(0.25, 0.8, 0.25, 1);
}

/* Image styles for smooth cross-device viewing */
.slides img {
    width: 100%;
    height: 100%;
    object-fit: cover; /* Ensures image fills the container without distortion */
    object-position: center; /* Centers the focal point of the image */
    flex-shrink: 0;
    display: block;
}

/* Slider Navigation Indicators (Dots) */
.slider-dots {
    text-align: center;
    margin-top: 15px;
    display: flex;
    justify-content: center;
    gap: 8px;
}

.dot {
    display: inline-block;
    width: 12px;
    height: 12px;
    background-color: #d1d8e0;
    border-radius: 50%;
    transition: all 0.3s ease;
}

.dot.active {
    background-color: #E67E22;
    transform: scale(1.2);
}

/* Message Box Below Slider */
.slider-message {
    margin-top: 30px;
    padding: 25px;
    background: #FFF9F2;
    border-left: 5px solid #E67E22;
    border-radius: 8px;
}

.slider-message p {
    font-size: 1.15rem;
    color: #333;
    line-height: 1.8;
    margin-bottom: 25px;
    text-align: justify;
}

/* CTA Button */
.cta-container {
    text-align: center;
}

.cta-button {
    display: inline-block;
    background: linear-gradient(135deg, #E67E22, #D35400);
    color: #fff;
    padding: 14px 35px;
    font-size: 1.15rem;
    font-weight: bold;
    text-decoration: none;
    border-radius: 30px;
    transition: all 0.3s ease;
    box-shadow: 0 4px 10px rgba(211, 84, 0, 0.3);
}

.cta-button i {
    margin-right: 8px;
}

.cta-button:hover {
    transform: translateY(-3px);
    box-shadow: 0 6px 15px rgba(211, 84, 0, 0.5);
    color: #fff;
}

/* Responsive Adjustments for Tablets */
@media (max-width: 992px) {
    .slider-message p {
        font-size: 1.1rem;
    }
}

/* Responsive Adjustments for Mobile Devices */
@media (max-width: 768px) {
    .gallery-section {
        padding: 15px;
        margin: 20px auto;
    }

    .gallery-header h2 {
        font-size: 1.5rem;
    }

    .gallery-header p {
        font-size: 0.95rem;
    }

    /* Change ratio for mobile to show faces/action more clearly */
    .slider-wrapper {
        aspect-ratio: 4/3; 
    }

    .slider-message {
        padding: 15px;
    }

    .slider-message p {
        font-size: 1.05rem;
        line-height: 1.6;
    }

    .cta-button {
        display: block;
        width: 100%;
        padding: 12px 20px;
        font-size: 1rem;
    }
}

/* =========================================
   ABOUT SHIVBODH TRUST SECTION
   ========================================= */

/* Main Section Wrapper */
.about-trust-section {
    background-color: #FDFBF7; /* Soft paper/creamy background */
    padding: 80px 20px;
    position: relative;
    overflow: hidden;
}

/* Container for Flexbox Layout */
.about-container {
    max-width: 1200px;
    margin: 0 auto;
    display: flex;
    flex-wrap: wrap; /* Allows wrapping on smaller screens */
    align-items: center;
    gap: 50px; /* Space between text and visual */
}

/* ----------------------------------
   LEFT SIDE: TEXT CONTENT
   ---------------------------------- */
.about-content {
    flex: 1; /* Takes up 50% space on desktop */
    min-width: 300px; /* Ensures it doesn't get too squeezed */
}

.section-tag {
    display: inline-block;
    color: #D35400; /* Dark Saffron */
    font-weight: 700;
    letter-spacing: 2px;
    text-transform: uppercase;
    font-size: 0.9rem;
    margin-bottom: 10px;
    font-family: 'Lato', sans-serif;
}

.section-title {
    font-family: 'Cinzel', serif;
    font-size: clamp(2rem, 4vw, 2.8rem); /* Scales smoothly across devices */
    color: #3E1E08; /* Deep brown */
    line-height: 1.2;
    margin: 0 0 15px 0;
}

.title-divider {
    width: 60px;
    height: 4px;
    background: #FF9933; /* Saffron */
    margin-bottom: 25px;
    border-radius: 2px;
}

.about-para {
    font-family: 'Alegreya', serif;
    font-size: 1.15rem;
    color: #5A2D0C;
    line-height: 1.7;
    margin-bottom: 20px;
    text-align: justify;
}

.about-para strong {
    color: #D35400;
}

/* List Items */
.mission-list {
    list-style: none;
    padding: 0;
    margin: 30px 0;
}

.mission-list li {
    display: flex;
    align-items: flex-start;
    gap: 15px;
    margin-bottom: 15px;
    font-family: 'Lato', sans-serif;
    font-size: 1.05rem;
    color: #4A2C0F;
}

.mission-list i {
    color: #FF9933;
    font-size: 1.2rem;
    margin-top: 4px;
}

/* Button */
.btn-read-more {
    display: inline-flex;
    align-items: center;
    gap: 10px;
    background: linear-gradient(135deg, #FF9933, #D35400);
    color: #fff;
    padding: 12px 30px;
    border-radius: 30px;
    text-decoration: none;
    font-family: 'Lato', sans-serif;
    font-weight: 700;
    font-size: 1rem;
    box-shadow: 0 5px 15px rgba(211, 84, 0, 0.3);
    transition: all 0.3s ease;
}

.btn-read-more:hover {
    transform: translateY(-3px);
    box-shadow: 0 8px 20px rgba(211, 84, 0, 0.5);
}

/* ----------------------------------
   RIGHT SIDE: VISUAL & MANDALA
   ---------------------------------- */
.about-visual {
    flex: 1; /* Takes up 50% space on desktop */
    min-width: 300px;
    position: relative;
    display: flex;
    justify-content: center;
    align-items: center;
    padding: 20px;
}

/* The Mandala Background */
.visual-circle-bg {
    position: relative;
    width: 350px; /* Base size for desktop */
    height: 350px;
    border-radius: 50%;
    background: radial-gradient(circle, rgba(255,153,51,0.1) 0%, rgba(211,84,0,0.05) 70%, transparent 100%);
    display: flex;
    justify-content: center;
    align-items: center;
}

/* Rotating Element */
.rotating-mandala {
    position: absolute;
    top: 0; left: 0; right: 0; bottom: 0;
    border: 2px dashed rgba(211, 84, 0, 0.4);
    border-radius: 50%;
    animation: rotateSlow 20s linear infinite;
}

.rotating-mandala::before {
    content: '';
    position: absolute;
    top: -10px; left: 50%; transform: translateX(-50%);
    width: 20px; height: 20px;
    background: #D35400;
    border-radius: 50%;
    box-shadow: 0 0 10px #FF9933;
}

@keyframes rotateSlow {
    0% { transform: rotate(0deg); }
    100% { transform: rotate(360deg); }
}

/* Center Om Symbol */
.center-om {
    font-size: 6rem;
    color: #D35400;
    text-shadow: 0 5px 15px rgba(0,0,0,0.1);
    z-index: 2;
    animation: pulseOm 3s infinite alternate;
}

@keyframes pulseOm {
    0% { transform: scale(0.95); opacity: 0.8; }
    100% { transform: scale(1.05); opacity: 1; }
}

/* Floating Stats Box */
.stats-floating-box {
    position: absolute;
    bottom: 0;
    right: 10%; /* Floats on the bottom right of the mandala */
    background: #fff;
    padding: 20px 30px;
    border-radius: 15px;
    display: flex;
    align-items: center;
    gap: 20px;
    box-shadow: 0 15px 30px rgba(0,0,0,0.1);
    border-bottom: 4px solid #D35400;
    z-index: 3;
}

.stat-item {
    text-align: center;
}

.stat-number {
    display: block;
    font-family: 'Cinzel', serif;
    font-size: 1.8rem;
    font-weight: 700;
    color: #D35400;
    line-height: 1;
}

.stat-label {
    font-family: 'Lato', sans-serif;
    font-size: 0.8rem;
    color: #5D6D7E;
    text-transform: uppercase;
    font-weight: 600;
    letter-spacing: 1px;
}

.stat-divider {
    width: 2px;
    height: 40px;
    background: #E5E7E9;
}

/* =========================================
   RESPONSIVE DESIGN (TABLET & MOBILE)
   ========================================= */

/* For Tablets (Screens smaller than 992px) */
@media screen and (max-width: 992px) {
    .about-container {
        flex-direction: column; /* Stacks text and visual vertically */
        text-align: center;
    }

    .title-divider {
        margin: 0 auto 25px auto; /* Centers the small orange line */
    }

    .about-para {
        text-align: center; /* Centers text for better reading on tablet */
    }

    .mission-list li {
        justify-content: center; /* Centers list items */
        text-align: left;
    }

    /* Adjust Visual Size for Tablet */
    .visual-circle-bg {
        width: 300px;
        height: 300px;
    }

    .stats-floating-box {
        right: 50%;
        transform: translateX(50%); /* Centers the floating box */
        bottom: -20px;
    }
}

