    padding: 0;
    box-sizing: border-box;
}

body {
    font-family: system-ui, 'Segoe UI', 'Roboto', sans-serif;
    background: #f5f7fc;
    background-image: radial-gradient(circle at 10% 20%, rgba(235, 245, 255, 0.6) 0%, #eef2fa 100%);
    min-height: 100vh;
}

/* Transparent background section */
.interactive-bg-section {
    background: transparent;
    min-height: 100vh;
    display: flex;
    align-items: center;
    justify-content: center;
    padding: 2rem;
}

/* Small container – no extra text, just buttons */
.small-container {
    max-width: 1100px;
    width: 100%;
    display: flex;
    flex-flow: row wrap;
    justify-content: center;
    gap: 0.8rem;
    background: transparent;
    padding: 0.5rem;
}

/* ===== BUTTON STYLES (ENHANCED WITH AUTO-RANDOM GLOW) ===== */
.nav-btn {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    background: rgba(20, 25, 45, 0.75);
    backdrop-filter: blur(2px);
    border: 1px solid rgba(255, 210, 130, 0.3);
    border-radius: 2.5rem;
    padding: 0.6rem 1.2rem;
    font-size: 0.9rem;
    font-weight: 500;
    color: #f0f0f0;
    text-decoration: none;
    white-space: nowrap;
    letter-spacing: 0.3px;
    box-shadow: 0 2px 6px rgba(0,0,0,0.1);
    cursor: pointer;
    transition: all 0.2s ease;
    will-change: transform, background, box-shadow;

    /* === AUTO RANDOM LIGHT-UP ANIMATION === 
       Each button gets a unique, chaotic rhythm */
    animation-name: randomGlow;
    animation-iteration-count: infinite;
    animation-timing-function: ease-in-out;
    animation-fill-mode: both;
}

/* Keyframes: creates a glowing “light-up” state with warm colours and shine */
@keyframes randomGlow {
    0% {
        background: rgba(20, 25, 45, 0.75);
        border-color: rgba(255, 210, 130, 0.3);
        color: #f0f0f0;
        box-shadow: 0 2px 6px rgba(0,0,0,0.1);
        transform: scale(1);
    }
    12% {
        background: radial-gradient(circle at 30% 20%, #ffdd99, #ffc861);
        background-color: #ffcf70;
        border-color: #ffbc3c;
        color: #1e1e2c;
        box-shadow: 0 0 14px 4px rgba(255, 200, 80, 0.9), 0 0 0 2px rgba(255, 210, 80, 0.5), 0 4px 14px rgba(0,0,0,0.2);
        transform: scale(1.02);
        text-shadow: 0 1px 0 rgba(255,255,200,0.6);
    }
    25% {
        background: rgba(20, 25, 45, 0.75);
        border-color: rgba(255, 210, 130, 0.3);
        color: #f0f0f0;
        box-shadow: 0 2px 6px rgba(0,0,0,0.1);
        transform: scale(1);
    }
    100% {
        background: rgba(20, 25, 45, 0.75);
        border-color: rgba(255, 210, 130, 0.3);
        color: #f0f0f0;
        box-shadow: 0 2px 6px rgba(0,0,0,0.1);
        transform: scale(1);
    }
}

/* Each button gets a random-looking mix of durations and delays 
   (up to 20 buttons, feels completely unpredictable) */
.nav-btn:nth-child(1) { animation-duration: 2.3s; animation-delay: 0.1s; }
.nav-btn:nth-child(2) { animation-duration: 3.7s; animation-delay: 0.7s; }
.nav-btn:nth-child(3) { animation-duration: 1.9s; animation-delay: 1.2s; }
.nav-btn:nth-child(4) { animation-duration: 4.2s; animation-delay: 0.3s; }
.nav-btn:nth-child(5) { animation-duration: 2.8s; animation-delay: 1.8s; }
.nav-btn:nth-child(6) { animation-duration: 3.1s; animation-delay: 0.9s; }
.nav-btn:nth-child(7) { animation-duration: 1.6s; animation-delay: 2.1s; }
.nav-btn:nth-child(8) { animation-duration: 3.9s; animation-delay: 0.4s; }
.nav-btn:nth-child(9) { animation-duration: 2.5s; animation-delay: 1.5s; }
.nav-btn:nth-child(10) { animation-duration: 4.5s; animation-delay: 0.0s; }
.nav-btn:nth-child(11) { animation-duration: 2.1s; animation-delay: 2.3s; }
.nav-btn:nth-child(12) { animation-duration: 3.3s; animation-delay: 0.6s; }
.nav-btn:nth-child(13) { animation-duration: 1.8s; animation-delay: 1.1s; }
.nav-btn:nth-child(14) { animation-duration: 3.5s; animation-delay: 1.9s; }
.nav-btn:nth-child(15) { animation-duration: 2.7s; animation-delay: 0.2s; }
.nav-btn:nth-child(16) { animation-duration: 4.0s; animation-delay: 1.3s; }
.nav-btn:nth-child(17) { animation-duration: 1.5s; animation-delay: 2.6s; }
.nav-btn:nth-child(18) { animation-duration: 3.2s; animation-delay: 0.5s; }
.nav-btn:nth-child(19) { animation-duration: 2.9s; animation-delay: 1.7s; }
.nav-btn:nth-child(20) { animation-duration: 3.8s; animation-delay: 2.0s; }

/* Hover effect remains interactive and overrides animation partially (more fun) */
.nav-btn:hover {
    background: rgba(255, 210, 130, 0.85);
    color: #1a1e2a;
    border-color: #ffcf88;
    transform: translateY(-2px);
    box-shadow: 0 6px 14px rgba(0,0,0,0.15);
    animation: none;   /* pause auto-random when hovered, gives user control */
}

.nav-btn:active {
    transform: translateY(0);
}

.nav-btn:focus-visible {
    outline: 2px solid #ffaa44;
    outline-offset: 2px;
}

/* Responsive: keep original adjustments */
@media (max-width: 768px) {
    .small-container {
        gap: 0.6rem;
    }
    .nav-btn {
        padding: 0.5rem 1rem;
        font-size: 0.85rem;
        white-space: nowrap;
    }
}

@media (max-width: 600px) {
    .nav-btn {
        padding: 0.45rem 0.9rem;
        font-size: 0.8rem;
    }
}

@media (max-width: 480px) {
    .small-container {
        gap: 0.5rem;
    }
    .nav-btn {
        padding: 0.4rem 0.8rem;
        font-size: 0.75rem;
        white-space: nowrap;
    }
}

@media (max-width: 380px) {
    .nav-btn {
        white-space: normal;
        text-align: center;
        min-width: 100px;
    }
}

/* WORK IN PROGRESS SECTION STYLES */

.campaigns-wip-section {
    background: linear-gradient(135deg, #1a1005 0%, #2C1B18 100%);
    padding: 120px 20px;
    position: relative;
    overflow: hidden;
    text-align: center;
}

/* Background Animated Icon */
.background-icon {
    position: absolute;
    top: 50%;
    left: 50%;
    transform: translate(-50%, -50%);
    font-size: 35rem;
    color: rgba(212, 175, 55, 0.02); /* Extremely faint gold */
    z-index: 0;
    pointer-events: none;
}

.wip-container {
    max-width: 900px;
    margin: 0 auto;
    position: relative;
    z-index: 1;
    background: rgba(0, 0, 0, 0.4);
    padding: 60px 40px;
    border-radius: 20px;
    border: 1px solid rgba(212, 175, 55, 0.2);
    backdrop-filter: blur(5px);
    box-shadow: 0 20px 50px rgba(0,0,0,0.5);
}

.wip-content .section-tag {
    font-family: 'Lato', sans-serif;
    color: #D4AF37; /* Gold */
    font-size: 1rem;
    font-weight: 700;
    letter-spacing: 3px;
    text-transform: uppercase;
    display: block;
    margin-bottom: 15px;
}

.wip-title {
    font-family: 'Cinzel', serif;
    font-size: clamp(2rem, 4vw, 3rem);
    color: #fff;
    line-height: 1.3;
    margin-bottom: 20px;
}

.title-divider.center {
    width: 80px;
    height: 3px;
    background-color: #D4AF37;
    margin: 0 auto 40px auto;
    border-radius: 2px;
}

/* THE MOTTO */
.wip-motto {
    font-family: 'Cinzel', serif;
    font-size: 2rem;
    color: #D4AF37;
    margin-bottom: 25px;
    line-height: 1.4;
    text-shadow: 0 2px 10px rgba(212, 175, 55, 0.3);
}

.wip-motto span {
    font-family: 'Lato', sans-serif;
    font-size: 1.4rem;
    color: #ddd;
    font-weight: 400;
}

.wip-desc {
    font-family: 'Alegreya', serif;
    font-size: 1.25rem;
    color: #ccc;
    line-height: 1.8;
    margin-bottom: 50px;
}

/* STATUS BUTTON / BOX */
.wip-status-box {
    display: inline-block;
    background: rgba(255, 255, 255, 0.05);
    padding: 25px 40px;
    border-radius: 15px;
    border-left: 4px solid #f39c12; /* Warning/Progress color */
}

.status-btn {
    display: inline-block;
    padding: 12px 30px;
    background-color: #f39c12;
    color: #111;
    font-family: 'Cinzel', serif;
    font-weight: 800;
    font-size: 1.2rem;
    border-radius: 50px;
    letter-spacing: 1px;
    margin-bottom: 15px;
    animation: pulseGlow 2s infinite;
}

.status-btn i {
    margin-right: 10px;
}

.status-note {
    font-family: 'Lato', sans-serif;
    font-size: 0.95rem;
    color: #aaa;
    max-width: 400px;
    margin: 0 auto;
    line-height: 1.5;
}

/* PULSE ANIMATION FOR BUTTON */
@keyframes pulseGlow {
    0% { box-shadow: 0 0 0 0 rgba(243, 156, 18, 0.7); }
    70% { box-shadow: 0 0 0 15px rgba(243, 156, 18, 0); }
    100% { box-shadow: 0 0 0 0 rgba(243, 156, 18, 0); }
}

/* RESPONSIVE DESIGN */
@media (max-width: 768px) {
    .wip-container {
        padding: 40px 20px;
        width: 95%;
    }

    .wip-motto {
        font-size: 1.5rem;
    }

    .wip-motto span {
        font-size: 1.1rem;
    }

    .wip-desc {
        font-size: 1.1rem;
    }

    .status-btn {
        font-size: 1rem;
        padding: 10px 20px;
    }
}
